(function() {
    'use strict';

    /**
     * LGBT Theme Toggle Handler
     * Manages the LGBT pride theme toggle functionality
     */
    
    function initLgbtTheme() {
        const toggleButton = document.getElementById('lgbtThemeToggle');
        const footerToggle = document.getElementById('lgbtThemeToggleFooter');
        
        // Check if it's Pride Month (June)
        const currentDate = new Date();
        const currentMonth = currentDate.getMonth() + 1; // JavaScript months are 0-indexed
        const isPrideMonth = currentMonth === 6;
        
        // Check if hostname is zaharaschaefer.gay
        const hostname = window.location.hostname.toLowerCase();
        const isGayDomain = hostname === 'zaharaschaefer.gay';
        
        // Check if theme is enabled via localStorage (only if not on gay domain and not Pride Month)
        const isThemeEnabled = !isGayDomain && !isPrideMonth && localStorage.getItem('lgbt_theme') === 'enabled';
        
        // Apply theme if enabled, on gay domain, or Pride Month
        if (isThemeEnabled || isGayDomain || isPrideMonth) {
            applyLgbtTheme(true);
            updateToggleButtons(true);
            
            // If on gay domain or Pride Month, ensure localStorage is set
            if (isGayDomain || isPrideMonth) {
                localStorage.setItem('lgbt_theme', 'enabled');
                setCookie('lgbt_theme', 'enabled', 365);
            }
        } else {
            applyLgbtTheme(false);
            updateToggleButtons(false);
        }

        // Add click handler to About page toggle
        if (toggleButton) {
            toggleButton.addEventListener('click', handleToggleClick);
        }

        // Add click handler to footer badge
        if (footerToggle) {
            footerToggle.addEventListener('click', handleToggleClick);
        }
    }

    function handleToggleClick(e) {
        // Prevent default link behavior
        e.preventDefault();
        e.stopPropagation();
        
        const html = document.documentElement;
        const hostname = window.location.hostname.toLowerCase();
        const isGayDomain = hostname === 'zaharaschaefer.gay';
        
        // Check if it's Pride Month (June)
        const currentDate = new Date();
        const currentMonth = currentDate.getMonth() + 1;
        const isPrideMonth = currentMonth === 6;
        
        const isCurrentlyEnabled = html.classList.contains('lgbt-theme');
        
        // If on gay domain or Pride Month, don't allow disabling
        if ((isGayDomain || isPrideMonth) && isCurrentlyEnabled) {
            // Show a message or just return
            window.trackEvent('lgbt_theme_toggle_blocked', {
                reason: isPrideMonth ? 'pride_month' : 'gay_domain',
                hostname: hostname
            });
            return;
        }
        
        const source = e.target.closest('#lgbtThemeToggleFooter') ? 'footer_badge' : 'about_page_easter_egg';
        
        if (isCurrentlyEnabled) {
            // Disable theme
            applyLgbtTheme(false);
            localStorage.removeItem('lgbt_theme');
            setCookie('lgbt_theme', 'disabled', 365);
        } else {
            // Enable theme
            applyLgbtTheme(true);
            localStorage.setItem('lgbt_theme', 'enabled');
            setCookie('lgbt_theme', 'enabled', 365);
        }
        
        // Track in PostHog
        window.trackEvent('lgbt_theme_toggled', {
            enabled: !isCurrentlyEnabled,
            hostname: hostname,
            source: source
        });
    }

    /**
     * Apply or remove LGBT theme
     */
    function applyLgbtTheme(enabled) {
        const html = document.documentElement;
        const link = document.getElementById('lgbt-theme-css');
        
        if (enabled) {
            html.classList.add('lgbt-theme');
            
            // Load CSS if not already loaded
            if (!link) {
                const cssLink = document.createElement('link');
                cssLink.id = 'lgbt-theme-css';
                cssLink.rel = 'stylesheet';
                cssLink.href = '/assets/css/lgbt-theme.css';
                document.head.appendChild(cssLink);
            }
        } else {
            html.classList.remove('lgbt-theme');
        }
        
        updateToggleButtons(enabled);
    }

    /**
     * Update toggle button appearance
     */
    function updateToggleButtons(enabled) {
        const toggleButton = document.getElementById('lgbtThemeToggle');
        const footerToggle = document.getElementById('lgbtThemeToggleFooter');
        
        const hostname = window.location.hostname.toLowerCase();
        const isGayDomain = hostname === 'zaharaschaefer.gay';
        
        // Check if it's Pride Month (June)
        const currentDate = new Date();
        const currentMonth = currentDate.getMonth() + 1;
        const isPrideMonth = currentMonth === 6;
        
        const alwaysEnabled = (isGayDomain || isPrideMonth) && enabled;
        const titleText = alwaysEnabled 
            ? (isPrideMonth 
                ? 'Pride theme is always enabled during Pride Month (June)' 
                : 'Pride theme is always enabled on this domain')
            : (enabled ? 'Click to disable Pride theme' : 'Click to enable Pride theme');
        
        // Update About page toggle
        if (toggleButton) {
            if (enabled) {
                toggleButton.setAttribute('aria-pressed', 'true');
                toggleButton.classList.add('active');
                
                if (alwaysEnabled) {
                    toggleButton.classList.add('always-enabled');
                } else {
                    toggleButton.classList.remove('always-enabled');
                }
                toggleButton.setAttribute('title', titleText);
            } else {
                toggleButton.setAttribute('aria-pressed', 'false');
                toggleButton.classList.remove('active', 'always-enabled');
                toggleButton.setAttribute('title', titleText);
            }
        }
        
        // Update footer badge
        if (footerToggle) {
            if (enabled) {
                footerToggle.classList.add('active');
                
                if (alwaysEnabled) {
                    footerToggle.classList.add('always-enabled');
                } else {
                    footerToggle.classList.remove('always-enabled');
                }
                footerToggle.setAttribute('title', titleText);
            } else {
                footerToggle.classList.remove('active', 'always-enabled');
                footerToggle.setAttribute('title', titleText);
            }
        }
    }

    /**
     * Set a cookie
     */
    function setCookie(name, value, days) {
        const expires = new Date();
        expires.setTime(expires.getTime() + (days * 24 * 60 * 60 * 1000));
        document.cookie = name + '=' + value + ';expires=' + expires.toUTCString() + ';path=/';
    }

    // Initialize on DOM ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLgbtTheme);
    } else {
        initLgbtTheme();
    }
})();

